/**
 * The variations Excel file (rulebook 1.52.0, owner decision 15 Nov: Excel replaces the CSV).
 *
 * The rows come from the rulebook (`variationExportRows`); this file only draws them. It writes a plain .xlsx
 * (Office Open XML) with `fflate`, which the app already ships: SheetJS community cannot write images, and the
 * company logo goes in a drawing part. Sheet 1 "Variations" has the header block (company, job, generated by / at in
 * the organisation zone), one row per variation and a totals row; sheet 2 "Line items" one row per line. Every text
 * cell is an inline string, so a value that starts with = + - @ is never read as a formula.
 */
import { strToU8, zipSync } from 'fflate'
import { currencySymbol, variationExportRows } from '@/lib/canonical'

type ExportRows = ReturnType<typeof variationExportRows>

export type VariationWorkbookLogo = { bytes: Uint8Array; type: 'png' | 'jpeg'; width: number; height: number }

export type VariationWorkbookInput = {
  rows: ExportRows
  companyName: string
  jobNumber: string
  jobName: string
  generatedBy: string
  /** "15 Nov 2026, 14:05" in the organisation zone. */
  generatedAt: string
  logo?: VariationWorkbookLogo | null
}

const STYLE = { text: 0, bold: 1, header: 2, title: 3, money: 4, number: 5, moneyBold: 6, numberBold: 7, wrap: 8, muted: 9 } as const

function xml(value: string): string {
  // Characters XML 1.0 cannot hold are dropped.
  // eslint-disable-next-line no-control-regex
  return value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F￾￿]/g, '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

function column(index: number): string {
  let n = index + 1
  let out = ''
  while (n > 0) {
    const r = (n - 1) % 26
    out = String.fromCharCode(65 + r) + out
    n = Math.floor((n - 1) / 26)
  }
  return out
}

type Cell = { value: string | number | null; style?: number }

function cellXml(ref: string, cell: Cell): string {
  const s = cell.style ? ` s="${cell.style}"` : ''
  if (cell.value == null || cell.value === '') return cell.style ? `<c r="${ref}"${s}/>` : ''
  if (typeof cell.value === 'number' && Number.isFinite(cell.value)) return `<c r="${ref}"${s}><v>${cell.value}</v></c>`
  return `<c r="${ref}"${s} t="inlineStr"><is><t xml:space="preserve">${xml(String(cell.value))}</t></is></c>`
}

function sheetXml(input: { rows: Cell[][]; widths: number[]; freezeRow?: number; drawing?: boolean; autoFilter?: string }): string {
  const cols = input.widths.map((width, i) => `<col min="${i + 1}" max="${i + 1}" width="${width}" customWidth="1"/>`).join('')
  const body = input.rows
    .map((row, r) => `<row r="${r + 1}">${row.map((cell, c) => cellXml(`${column(c)}${r + 1}`, cell)).join('')}</row>`)
    .join('')
  const pane = input.freezeRow
    ? `<sheetViews><sheetView workbookViewId="0"><pane ySplit="${input.freezeRow}" topLeftCell="A${input.freezeRow + 1}" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>`
    : '<sheetViews><sheetView workbookViewId="0"/></sheetViews>'
  return (
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">' +
    pane +
    `<cols>${cols}</cols><sheetData>${body}</sheetData>` +
    (input.autoFilter ? `<autoFilter ref="${input.autoFilter}"/>` : '') +
    (input.drawing ? '<drawing r:id="rId1"/>' : '') +
    '</worksheet>'
  )
}

function stylesXml(currency: string): string {
  const symbol = currencySymbol(currency).replace(/"/g, '')
  const moneyFormat = xml(`"${symbol}"#,##0.00`)
  return (
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">' +
    `<numFmts count="2"><numFmt numFmtId="164" formatCode="${moneyFormat}"/><numFmt numFmtId="165" formatCode="#,##0.##"/></numFmts>` +
    '<fonts count="5">' +
    '<font><sz val="11"/><name val="Calibri"/></font>' +
    '<font><b/><sz val="11"/><name val="Calibri"/></font>' +
    '<font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font>' +
    '<font><b/><sz val="16"/><color rgb="FF0C2350"/><name val="Calibri"/></font>' +
    '<font><sz val="10"/><color rgb="FF5B6475"/><name val="Calibri"/></font>' +
    '</fonts>' +
    '<fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>' +
    '<fill><patternFill patternType="solid"><fgColor rgb="FF0C2350"/><bgColor indexed="64"/></patternFill></fill></fills>' +
    '<borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border>' +
    '<border><left/><right/><top style="thin"><color rgb="FF0C2350"/></top><bottom/><diagonal/></border></borders>' +
    '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>' +
    '<cellXfs count="10">' +
    '<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"><alignment vertical="top"/></xf>' +
    '<xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"><alignment vertical="top"/></xf>' +
    '<xf numFmtId="0" fontId="2" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="center" wrapText="1"/></xf>' +
    '<xf numFmtId="0" fontId="3" fillId="0" borderId="0" xfId="0" applyFont="1"/>' +
    '<xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"><alignment vertical="top"/></xf>' +
    '<xf numFmtId="165" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"><alignment vertical="top"/></xf>' +
    '<xf numFmtId="164" fontId="1" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyBorder="1"/>' +
    '<xf numFmtId="165" fontId="1" fillId="0" borderId="1" xfId="0" applyNumberFormat="1" applyFont="1" applyBorder="1"/>' +
    '<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>' +
    '<xf numFmtId="0" fontId="4" fillId="0" borderId="0" xfId="0" applyFont="1"/>' +
    '</cellXfs>' +
    '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>' +
    '</styleSheet>'
  )
}

const MONEY_KEYS = new Set(['customTotal', 'subcontractorTotal', 'totalCost', 'cost', 'lineTotal'])
const NUMBER_KEYS = new Set(['labourHours', 'materialLines', 'evidenceCount', 'quantity', 'hours'])
const WRAP_KEYS = new Set(['description', 'heading', 'previousNumbers'])

function styleFor(key: string, value: unknown): number {
  if (typeof value === 'number') return MONEY_KEYS.has(key) ? STYLE.money : NUMBER_KEYS.has(key) ? STYLE.number : STYLE.text
  return WRAP_KEYS.has(key) ? STYLE.wrap : STYLE.text
}

/** Pixel size → EMU (Excel drawings: 9525 EMU per pixel). */
const EMU = 9525

function drawingXml(logo: VariationWorkbookLogo, columnIndex: number): string {
  const scale = Math.min(180 / logo.width, 60 / logo.height, 1)
  const cx = Math.round(logo.width * scale * EMU)
  const cy = Math.round(logo.height * scale * EMU)
  return (
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">' +
    `<xdr:oneCellAnchor><xdr:from><xdr:col>${columnIndex}</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>0</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from>` +
    `<xdr:ext cx="${cx}" cy="${cy}"/>` +
    '<xdr:pic><xdr:nvPicPr><xdr:cNvPr id="2" name="Company logo" descr="Company logo"/><xdr:cNvPicPr><a:picLocks noChangeAspect="1"/></xdr:cNvPicPr></xdr:nvPicPr>' +
    '<xdr:blipFill><a:blip r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill>' +
    `<xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic>` +
    '<xdr:clientData/></xdr:oneCellAnchor></xdr:wsDr>'
  )
}

/** The .xlsx bytes. */
export function buildVariationWorkbook(input: VariationWorkbookInput): Uint8Array {
  const { rows } = input
  const summaryColumns = rows.summaryColumns.filter((col) => rows.includeCost || !MONEY_KEYS.has(col.key))
  const lineColumns = rows.lineColumns.filter((col) => rows.includeCost || !MONEY_KEYS.has(col.key))
  const header: Cell[][] = [
    [{ value: 'Variations', style: STYLE.title }],
    [{ value: 'Company', style: STYLE.bold }, { value: input.companyName }],
    [{ value: 'Job', style: STYLE.bold }, { value: [input.jobNumber, input.jobName].filter(Boolean).join(' · ') }],
    [{ value: 'Generated', style: STYLE.bold }, { value: [input.generatedAt, input.generatedBy ? `by ${input.generatedBy}` : ''].filter(Boolean).join(' ') }],
    [],
  ]
  const summaryHead = summaryColumns.map((col) => ({ value: col.label, style: STYLE.header }))
  const summaryBody = rows.summaryRows.map((row) =>
    summaryColumns.map((col) => {
      const value = (row as Record<string, unknown>)[col.key] as string | number | null
      return { value, style: styleFor(col.key, value) }
    })
  )
  const totals = rows.summaryTotals as Record<string, unknown>
  const totalsRow = summaryColumns.map((col, index): Cell => {
    if (index === 0) return { value: `Totals (${rows.summaryTotals.count})`, style: STYLE.bold }
    const key = col.key === 'materialLines' ? 'materialLines' : col.key
    const value = totals[key]
    if (typeof value !== 'number') return { value: null, style: STYLE.numberBold }
    return { value, style: MONEY_KEYS.has(col.key) ? STYLE.moneyBold : STYLE.numberBold }
  })
  const firstTableRow = header.length + 1
  const sheet1Rows: Cell[][] = [...header, summaryHead, ...summaryBody, totalsRow]
  const sheet1 = sheetXml({
    rows: sheet1Rows,
    widths: summaryColumns.map((col) => (col.key === 'description' ? 48 : col.key === 'heading' ? 32 : col.key === 'previousNumbers' ? 22 : col.key === 'raisedBy' ? 20 : 14)),
    freezeRow: firstTableRow,
    drawing: Boolean(input.logo),
    autoFilter: summaryBody.length > 0 ? `A${firstTableRow}:${column(summaryColumns.length - 1)}${firstTableRow + summaryBody.length}` : undefined,
  })
  const lineHead = lineColumns.map((col) => ({ value: col.label, style: STYLE.header }))
  const lineBody = rows.lineRows.map((row) =>
    lineColumns.map((col) => {
      const value = (row as Record<string, unknown>)[col.key] as string | number | null
      return { value, style: styleFor(col.key, value) }
    })
  )
  const sheet2Rows: Cell[][] = [
    [{ value: 'Line items', style: STYLE.title }],
    [{ value: [input.jobNumber, input.jobName].filter(Boolean).join(' · '), style: STYLE.muted }],
    [],
    lineHead,
    ...lineBody,
  ]
  const sheet2 = sheetXml({
    rows: sheet2Rows,
    widths: lineColumns.map((col) => (col.key === 'description' ? 44 : col.key === 'subcontractor' ? 24 : col.key === 'type' ? 15 : 12)),
    freezeRow: 4,
    autoFilter: lineBody.length > 0 ? `A4:${column(lineColumns.length - 1)}${4 + lineBody.length}` : undefined,
  })
  const media = input.logo ? `image1.${input.logo.type === 'png' ? 'png' : 'jpeg'}` : ''
  const files: Record<string, Uint8Array> = {
    '[Content_Types].xml': strToU8(
      '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">' +
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>' +
        '<Default Extension="xml" ContentType="application/xml"/>' +
        '<Default Extension="png" ContentType="image/png"/><Default Extension="jpeg" ContentType="image/jpeg"/>' +
        '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>' +
        '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>' +
        '<Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>' +
        '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>' +
        (input.logo ? '<Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>' : '') +
        '</Types>'
    ),
    '_rels/.rels': strToU8(
      '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>' +
        '</Relationships>'
    ),
    'xl/workbook.xml': strToU8(
      '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">' +
        '<sheets><sheet name="Variations" sheetId="1" r:id="rId1"/><sheet name="Line items" sheetId="2" r:id="rId2"/></sheets>' +
        (summaryBody.length > 0 || lineBody.length > 0
          ? '<definedNames>' +
            (summaryBody.length > 0 ? `<definedName name="_xlnm._FilterDatabase" localSheetId="0" hidden="1">Variations!$A$${firstTableRow}:$${column(summaryColumns.length - 1)}$${firstTableRow + summaryBody.length}</definedName>` : '') +
            (lineBody.length > 0 ? `<definedName name="_xlnm._FilterDatabase" localSheetId="1" hidden="1">'Line items'!$A$4:$${column(lineColumns.length - 1)}$${4 + lineBody.length}</definedName>` : '') +
            '</definedNames>'
          : '') +
        '</workbook>'
    ),
    'xl/_rels/workbook.xml.rels': strToU8(
      '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>' +
        '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/>' +
        '<Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>' +
        '</Relationships>'
    ),
    'xl/styles.xml': strToU8(stylesXml(rows.currency)),
    'xl/worksheets/sheet1.xml': strToU8(sheet1),
    'xl/worksheets/sheet2.xml': strToU8(sheet2),
  }
  if (input.logo) {
    files['xl/worksheets/_rels/sheet1.xml.rels'] = strToU8(
      '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
        '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing1.xml"/>' +
        '</Relationships>'
    )
    files['xl/drawings/drawing1.xml'] = strToU8(drawingXml(input.logo, Math.max(3, summaryColumns.length - 3)))
    files['xl/drawings/_rels/drawing1.xml.rels'] = strToU8(
      '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
        `<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/${media}"/>` +
        '</Relationships>'
    )
    files[`xl/media/${media}`] = input.logo.bytes
  }
  return zipSync(files, { level: 6 })
}

/** Width and height of a PNG or JPEG from its header; null for anything else (the file is made without a logo). */
export function imageSize(bytes: Uint8Array): { type: 'png' | 'jpeg'; width: number; height: number } | null {
  if (bytes.length > 24 && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
    const width = view.getUint32(16)
    const height = view.getUint32(20)
    return width > 0 && height > 0 ? { type: 'png', width, height } : null
  }
  if (bytes.length > 4 && bytes[0] === 0xff && bytes[1] === 0xd8) {
    let i = 2
    while (i + 9 < bytes.length) {
      if (bytes[i] !== 0xff) {
        i += 1
        continue
      }
      const marker = bytes[i + 1]
      const length = (bytes[i + 2] << 8) | bytes[i + 3]
      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
        const height = (bytes[i + 5] << 8) | bytes[i + 6]
        const width = (bytes[i + 7] << 8) | bytes[i + 8]
        return width > 0 && height > 0 ? { type: 'jpeg', width, height } : null
      }
      if (length < 2) return null
      i += 2 + length
    }
  }
  return null
}

/** Fetches the company logo for the workbook; null when there is none or it is not a PNG or JPEG. */
export async function loadWorkbookLogo(url: string | null | undefined): Promise<VariationWorkbookLogo | null> {
  if (!url) return null
  try {
    const response = await fetch(url)
    if (!response.ok) return null
    const bytes = new Uint8Array(await response.arrayBuffer())
    const size = imageSize(bytes)
    return size ? { bytes, ...size } : null
  } catch (error) {
    console.warn('[variations] the company logo could not be read for the Excel file', error)
    return null
  }
}
